// ─── CONFIGURE ────────────────────────────────────────────────────────────
const BUSINESS_NAME = 'Your Business';
const TIMEZONE      = 'Europe/London';
const WORKING_DAYS  = [1, 2, 3, 4, 5];  // 0 = Sunday, 1 = Monday … 6 = Saturday
const OPEN_HOUR     = 8;                // 08:00
const CLOSE_HOUR    = 17;               // 17:00 (calls at 16:59 count as in hours)

const IN_HOURS_MESSAGE =
  `Sorry we missed your call — this is ${BUSINESS_NAME}. ` +
  `We're on a job and will ring you back as soon as we're free. ` +
  `If it's urgent, reply to this text and we'll see it.`;

const OUT_OF_HOURS_MESSAGE =
  `Thanks for calling ${BUSINESS_NAME}. We're closed right now, ` +
  `but we've logged your number and will call you back when we open. ` +
  `Reply to this text if you'd like to leave details.`;
// ─── END CONFIGURE ────────────────────────────────────────────────────────

// Twilio reports the outcome of every call. These three mean nobody picked up.
const MISSED_STATUSES = ['no-answer', 'busy', 'failed'];

const results = [];

for (const item of $input.all()) {
  // Twilio posts form-encoded data, which n8n puts under `body`.
  const call = item.json.body ?? item.json;

  const status    = String(call.CallStatus ?? '').toLowerCase();
  const direction = String(call.Direction ?? '').toLowerCase();
  const caller    = call.From ?? '';

  // Ignore answered calls, calls still in progress, and our own outbound calls.
  if (!MISSED_STATUSES.includes(status)) continue;
  if (direction && !direction.startsWith('inbound')) continue;
  if (!caller) continue;

  // Work out local time properly rather than trusting the server's clock.
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-GB', {
      timeZone: TIMEZONE,
      weekday: 'short',
      hour: '2-digit',
      hour12: false,
    })
      .formatToParts(new Date())
      .map((p) => [p.type, p.value]),
  );

  const dayIndex = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[parts.weekday];
  const hour = parseInt(parts.hour, 10);
  const inHours = WORKING_DAYS.includes(dayIndex) && hour >= OPEN_HOUR && hour < CLOSE_HOUR;

  results.push({
    json: {
      caller,
      called: call.To ?? '',
      callSid: call.CallSid ?? '',
      callStatus: status,
      receivedAt: new Date().toISOString(),
      inHours,
      smsBody: inHours ? IN_HOURS_MESSAGE : OUT_OF_HOURS_MESSAGE,
    },
  });
}

// Returning nothing stops the workflow here — the call was answered, so
// there is nobody to text.
return results;

// ─── CONFIGURE ────────────────────────────────────────────────────────────
const DEDUPE_HOURS = 24; // don't text the same number again within this window; 0 = always text
// ─── END CONFIGURE ────────────────────────────────────────────────────────

const call = $('Was the call missed?').first().json;

// Rows returned by the Sheets lookup (may be a single empty item when the
// caller has never rung before — alwaysOutputData is on).
const rows = $input.all().map((i) => i.json).filter((r) => r && r.Caller);

const cutoff = Date.now() - DEDUPE_HOURS * 60 * 60 * 1000;

const alreadyTexted =
  DEDUPE_HOURS > 0 &&
  rows.some((r) => {
    if (String(r.Caller) !== String(call.caller)) return false;
    if (String(r.Texted ?? '').toLowerCase() !== 'yes') return false;
    const t = Date.parse(r.Time);
    return !isNaN(t) && t >= cutoff;
  });

return [{ json: { ...call, alreadyTexted } }];

